using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Cube of Force (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class CubeOfForce2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("cube-of-force", null, 0, MagicItemType.WondrousItem, ItemRarity.Rare, true, ContentSource.Srd51,
			Charges(36, ItemRecharge.LongRest, "1d20"),
			("Cubo di forza", "Oggetto meraviglioso, raro (richiede sintonia)",
			"Questo cubo ha uno spigolo di circa 2,5 cm. Su ogni faccia è raffigurato un simbolo diverso, che può essere premuto. Inizialmente il cubo possiede 36 cariche e recupera 1d20 cariche consumate all'alba di ogni giorno.\n\nIl personaggio può usare un'azione per premere una delle facce del cubo, consumando un numero di cariche basato sulla faccia scelta, come indicato nella tabella \"Facce del cubo di forza\". Ogni faccia ha un effetto diverso. Se al cubo non rimangono abbastanza cariche, non accade nulla. Altrimenti si materializza una barriera di forza invisibile, che forma un cubo con spigolo di 4,5 metri. La barriera è centrata sul personaggio, si sposta insieme a lui e dura 1 minuto, fino a quando il personaggio non usa un'azione per premere la sesta faccia o finché il cubo non termina le cariche. È possibile cambiare l'effetto della barriera premendo una faccia diversa del cubo e consumando il relativo numero di cariche: in questo caso anche la durata riparte da zero.\n\nSe il movimento del personaggio porta la barriera in contatto con un corpo solido che non può passare attraverso il cubo, il personaggio non può avvicinarsi ulteriormente a quell'oggetto fintantoché la barriera resta attiva.\n\n**Facce del cubo di forza**\n\n| Faccia | Cariche | Effetto |\n|---|---|---|\n| 1 | 1 | Gas, vento e nebbia non possono attraversare la barriera. |\n| 2 | 2 | Il materiale inorganico non può attraversare la barriera. Pareti, pavimenti e soffitti possono attraversarla a discrezione del personaggio. |\n| 3 | 3 | Il materiale organico non può attraversare la barriera. |\n| 4 | 4 | Gli effetti degli incantesimi non possono attraversare la barriera. |\n| 5 | 5 | Nulla può attraversare la barriera. Pareti, pavimenti e soffitti possono attraversarla a discrezione del personaggio. |\n| 6 | 0 | La barriera si disattiva. |\n\nIl cubo perde cariche quando la barriera viene bersagliata da certi incantesimi o entra in contatto con gli effetti di certi incantesimi o oggetti magici, come indicato dalla tabella seguente.\n\n| Incantesimo o oggetto | Cariche perse |\n|---|---|\n| Corno della distruzione | 1d10 |\n| Disintegrazione | 1d12 |\n| Muro di fuoco | 1d4 |\n| Passapareti | 1d6 |\n| Spruzzo prismatico | 1d20 |"),
			("Cube of Force", "Wondrous item, rare (requires attunement)",
			"This cube is about an inch across. Each face has a distinct marking on it that can be pressed. The cube starts with 36 charges, and it regains 1d20 expended charges daily at dawn.\n\nYou can use an action to press one of the cube's faces, expending a number of charges based on the chosen face, as shown in the Cube of Force Faces table. Each face has a different effect. If the cube has insufficient charges remaining, nothing happens. Otherwise, a barrier of invisible force springs into existence, forming a cube 15 feet on a side. The barrier is centered on you, moves with you, and lasts for 1 minute, until you use an action to press the cube's sixth face, or the cube runs out of charges. You can change the barrier's effect by pressing a different face of the cube and expending the requisite number of charges, resetting the duration.\n\nIf your movement causes the barrier to come into contact with a solid object that can't pass through the cube, you can't move any closer to that object as long as the barrier remains.\n\nCube of Force Faces\n\n| Face | Charges | Effect |\n|---|---|---|\n| 1 | 1 | Gases, wind, and fog can't pass through the barrier.\n| 2 | 2 | Nonliving matter can't pass through the barrier. Walls, floors, and ceilings can pass through at your discretion.\n| 3 | 3 | Living matter can't pass through the barrier.\n| 4 | 4 | Spell effects can't pass through the barrier.\n| 5 | 5 | Nothing can pass through the barrier. Walls, floors, and ceilings can pass through at your discretion.\n| 6 | 0 | The barrier deactivates.\n\nThe cube loses charges when the barrier is targeted by certain spells or comes into contact with certain spell or magic item effects, as shown in the table below.\n\n| Spell or Item | Charges Lost |\n|---|---|\n| Disintegrate | 1d12 |\n| Horn of blasting | 1d10 |\n| Passwall | 1d6 |\n| Prismatic spray | 1d20 |\n| Wall of fire | 1d4 |", null));
	}
}
